import sys
from functools import lru_cache

d = sys.stdin.read().split()
n, k = int(d[0]), int(d[1])
arr = tuple(sorted(int(x) for x in d[2:2 + n]))

@lru_cache(maxsize=None)
def best(state, left):
    if left == 0:
        return sum(state)
    res = None
    for i in range(len(state)):
        nxt = list(state)
        nxt[i] = -(-nxt[i] // 2)
        v = best(tuple(sorted(nxt)), left - 1)
        if res is None or v < res:
            res = v
    return res

print(best(arr, k))

